import {onDutySummary} from './onDutySummaryV110381.js';
import {onDutyIntervals} from './onDutyIntervalsV110380.js';
import React, { useEffect, useRef } from 'react';
import { durLabel, timeLabel } from '../../shared/utils/time.js';
import { color, label } from '../../shared/utils/status.js';
import { sanitizeLogText, combineLogText } from '../../shared/utils/logText.js';
import { shipmentContextLabel } from '../../core/routes/shipmentCarryover.js';

export default function EventList({ events, selectedId, selectMode, selectedIds = [], onSelect, onToggleSelected, onOpenEdit, onCorrectCarry }) {
  const refs = useRef({});

  useEffect(() => {
    if (selectedId && refs.current[selectedId]) {
      refs.current[selectedId].scrollIntoView({ block:'nearest', behavior:'smooth' });
    }
  }, [selectedId]);

  if (!events.length) {
    return (
      <div className="events clean-events">
        <div className="empty-events-card">
          <b>No events yet</b>
          <span>Today stays clean. Events appear as you create them.</span>
        </div>
      </div>
    );
  }

  const renderEvent = (event, grouped=false) => {
        const selected = selectedId === event.id;
        const checked = selectedIds.includes(event.id);
        const continuityOnly = !!event.displayOnly || !!event.carriedFromPreviousDay || !!event.syntheticCoverage;
        const loc = `${event.city || ''}${event.state ? `, ${event.state}` : ''}`.trim();
        const transitionSummary = sanitizeLogText(event.transitionSummary || '');
        const reasonNote = sanitizeLogText((Array.isArray(event.reasons) ? event.reasons : []).join(' · '));
        const rawNote = sanitizeLogText(event.note || '');
        const cleanNote = event.status === 'ON' && reasonNote
          ? combineLogText(reasonNote, /^on duty$/i.test(rawNote) ? '' : rawNote)
          : rawNote;
        const displayNote = transitionSummary && !cleanNote.includes(transitionSummary)
          ? [cleanNote, transitionSummary].filter(Boolean).join(' · ')
          : cleanNote;
        const activityText = `${reasonNote} ${event.note || ''} ${event.description || ''}`;
        const loadActivity = event.status === 'ON' && /pickup|pick up|loading|delivery|unloading/i.test(activityText);
        const shippingDocs = String(event.shippingDocs || event.loadNo || event.bol || event.po || '').trim();
        const destination = String(
          event.destination
          || [event.destinationCity, event.destinationState].filter(Boolean).join(', ')
          || ''
        ).trim();
        const activityRouteMeta = loadActivity
          ? [shippingDocs ? `BOL ${shippingDocs}` : '', destination ? `Going to ${destination}` : ''].filter(Boolean).join(' · ')
          : '';
        const routeMeta = [activityRouteMeta, shipmentContextLabel(event.shipmentContextV110367)].filter(Boolean).join(' · ');
        return (
          <div
            key={event.id}
            data-log-event-id={event.id}
            ref={(el) => { refs.current[event.id] = el; }}
            className={`event-row clean-event-row ${selected ? 'selected' : ''} ${selectMode && checked ? 'bulk-selected checked' : ''} ${selectMode ? 'selectable' : ''} ${continuityOnly ? 'continuity-only-v11026' : ''}`}
            onClick={() => selectMode ? (!continuityOnly && onToggleSelected(event.id)) : onSelect?.(event.id)}
          >
            {selectMode && !continuityOnly ? (
              <input className="event-check" type="checkbox" readOnly checked={checked} />
            ) : !grouped ? (
              <div className="event-badge" style={{ background: color(event.status) }}>{event.status}</div>
            ) : null}

            <div className="event-content">
              <div className="event-title-line">
                {!grouped && <b>{label(event.status)}</b>}
                <span>{timeLabel(event.startMin, true)} – {event.isLive ? 'Now' : timeLabel(event.endMin, true)} · {durLabel(event.endMin - event.startMin)}</span>
              </div>
              <div className="event-loc">{loc}</div>
              {displayNote && <div className="event-note">{displayNote}</div>}
              {routeMeta && <div className="event-route-meta">{routeMeta}</div>}
            </div>

            {continuityOnly ? (
              <button type="button" className="blue-edit carry-edit-action-v110365" aria-label="Edit continued status" onClick={(e) => { e.stopPropagation(); onCorrectCarry?.(event.id); }}>Edit</button>
            ) : selectMode ? (
              <button className="blue-edit select-tick-v9589" onClick={(e)=>{ e.stopPropagation(); onToggleSelected(event.id); }}>
                {checked ? 'Selected' : 'Select'}
              </button>
            ) : selected ? (
              <button className="blue-edit motive-edit-reveal-v11027" aria-label="Edit selected event" onClick={(e)=>{ e.stopPropagation(); onOpenEdit(event.id); }}>Edit</button>
            ) : (
              <span className="event-edit-placeholder-v11027" aria-hidden="true" />
            )}
          </div>
        );
  };
  return <div className="events clean-events">
    <style>{`.on-duty-interval-v110380{border:1px solid #dce4eb;border-radius:16px;margin:10px 0;overflow:hidden;background:transparent}
.on-duty-interval-v110380 .on-duty-heading{display:flex;gap:12px;align-items:center;padding:16px 14px}
.on-duty-interval-v110380 .on-duty-heading .event-title-line{display:flex;flex-direction:column;align-items:flex-start}
.on-duty-interval-v110380 .event-row.clean-event-row{margin:0!important;border:0!important;border-top:1px solid #e8edf2!important;border-radius:0!important;padding:12px 14px!important;min-width:0}
.on-duty-interval-v110380 .event-content{min-width:0;overflow-wrap:anywhere}
.on-duty-interval-v110380 .event-title-line{font-size:.86em}
.on-duty-interval-v110380 .on-duty-heading .event-title-line{font-size:1em}
.on-duty-summary-v110381{padding:0 14px 12px;overflow-wrap:anywhere;min-width:0}
.on-duty-details-v110381>summary{cursor:pointer;color:#2456cf;padding:10px 14px;font-weight:700;min-height:44px;box-sizing:border-box}
.on-duty-details-v110381:not([open])>.event-row{display:none!important}`}</style>
    {onDutyIntervals(events).map(group=>{
      if(group.length===1)return renderEvent(group[0]);
      const first=group[0],last=group.at(-1),summary=onDutySummary(group);
      return <section key={first.id} className="on-duty-interval-v110380" data-on-duty-interval={group.map(e=>e.id).join(' ')} aria-label="Continuous On Duty">
        <div className="on-duty-heading">
          <div className="event-badge" style={{background:color('ON')}}>ON</div>
          <div className="event-title-line"><b>{label('ON')}</b><span>{timeLabel(first.startMin,true)} – {last.isLive?'Now':timeLabel(last.endMin,true)} · {durLabel(last.endMin-first.startMin)}</span></div>
        </div>
        <div className="on-duty-summary-v110381">
          <div className="event-loc">{summary.locations.join(' → ')}</div>
          {summary.note && <div className="event-note">{summary.note}</div>}
          {summary.routes.map((route,index)=><div className="event-route-meta" key={index}>{route}</div>)}
        </div>
        <details className="on-duty-details-v110381" open={selectMode || undefined}>
          <summary>Edit activities</summary>
          {group.map(event=>renderEvent(event,true))}
        </details>
      </section>;
    })}
  </div>;
}
